// Decade counter (10-bit, up-down)
module TopModule(input clk, input reset, output reg [3:0] q);
    reg [3:0] cnt;
    reg up;
    always @(posedge clk) begin
        if (reset) begin
            cnt <= 4'd0;
            up <= 1'b1;
        end else begin
            if (up) begin
                if (cnt == 4'd9) up <= 1'b0;
                else cnt <= cnt + 4'd1;
            end else begin
                if (cnt == 4'd0) up <= 1'b1;
                else cnt <= cnt - 4'd1;
            end
        end
        q <= cnt;
    end
endmodule

