    always @(posedge clk) begin
        if (reset) begin
            r0 <= 4'd0;
            r1 <= 4'd0;
            r2 <= 4'd0;
            r3 <= 4'd0;
            r4 <= 4'd0;
            r5 <= 4'd0;
            r6 <= 4'd0;
            r7 <= 4'd0;
            r8 <= 4'd0;
            r9 <= 4'd0;
            q <= 4'd0;
        end else begin
            r0 <= 4'd1;
            r1 <= r0;
            r2 <= r1;
            r3 <= r2;
            r4 <= r3;
            r5 <= r4;
            r6 <= r5;
            r7 <= r6;
            r8 <= r7;
            r9 <= r8;
